import { useEffect, useId, useRef } from "react";
import type { KeyboardEvent } from "react";
import "./ConfirmDialog.css";

export interface ConfirmDialogProps {
  open: boolean;
  noteTitle: string;
  onCancel: () => void;
  onConfirm: () => void;
}

const FOCUSABLE_SELECTOR =
  'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

export function ConfirmDialog({ open, noteTitle, onCancel, onConfirm }: ConfirmDialogProps) {
  const titleId = useId();
  const descriptionId = useId();
  const panelRef = useRef<HTMLDivElement>(null);
  const cancelRef = useRef<HTMLButtonElement>(null);

  // Move focus into the dialog when it opens, and return it to the
  // previously focused element when it closes or unmounts.
  useEffect(() => {
    if (!open) {
      return;
    }
    const previouslyFocused =
      document.activeElement instanceof HTMLElement ? document.activeElement : null;

    // Cancel is the safe default for a destructive action, so it gets focus first.
    cancelRef.current?.focus();

    return () => {
      previouslyFocused?.focus();
    };
  }, [open]);

  if (!open) {
    return null;
  }

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key === "Escape") {
      event.preventDefault();
      onCancel();
      return;
    }

    if (event.key !== "Tab" || !panelRef.current) {
      return;
    }

    // Keep Tab and Shift+Tab cycling inside the dialog.
    const panel = panelRef.current;
    const focusable = Array.from(panel.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR));
    if (focusable.length === 0) {
      return;
    }

    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    const active = document.activeElement;
    const focusIsInside = active instanceof Node && panel.contains(active);

    if (event.shiftKey && (active === first || !focusIsInside)) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && (active === last || !focusIsInside)) {
      event.preventDefault();
      first.focus();
    }
  }

  return (
    <div className="confirm-scrim">
      <div
        ref={panelRef}
        className="confirm-dialog"
        role="alertdialog"
        aria-modal="true"
        aria-labelledby={titleId}
        aria-describedby={descriptionId}
        onKeyDown={handleKeyDown}
      >
        <h2 id={titleId} className="confirm-title">
          Delete this note?
        </h2>
        <p id={descriptionId} className="confirm-body">
          “{noteTitle}” will be deleted. This cannot be undone.
        </p>
        <div className="confirm-actions">
          <button
            ref={cancelRef}
            type="button"
            className="confirm-button"
            onClick={onCancel}
          >
            Cancel
          </button>
          <button
            type="button"
            className="confirm-button confirm-button--primary"
            onClick={onConfirm}
          >
            Delete
          </button>
        </div>
      </div>
    </div>
  );
}
