.confirm-scrim {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 1rem;
  background: color-mix(in srgb, var(--slide) 70%, transparent);
  z-index: 1000;
}

.confirm-dialog {
  box-sizing: border-box;
  width: min(90vw, 28rem);
  padding: clamp(1rem, 0.8rem + 1vw, 1.5rem);
  border: 1px solid var(--hair);
  border-radius: 16px;
  background: var(--slide);
  color: var(--ink);
  box-shadow: 0 12px 40px color-mix(in srgb, var(--ink) 18%, transparent);
  font: inherit;
}

.confirm-title {
  margin: 0 0 0.5rem;
  font: inherit;
  font-size: clamp(1.1rem, 1rem + 0.6vw, 1.4rem);
  font-weight: 600;
  color: var(--ink);
}

.confirm-body {
  margin: 0 0 1.25rem;
  font: inherit;
  font-size: clamp(0.9rem, 0.85rem + 0.3vw, 1rem);
  line-height: 1.5;
  color: var(--muted);
  overflow-wrap: anywhere;
}

.confirm-actions {
  display: flex;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.confirm-button {
  font: inherit;
  font-size: clamp(0.9rem, 0.85rem + 0.25vw, 1rem);
  padding: 0.5rem 1.1rem;
  border: 1px solid var(--ink);
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition: border-color 150ms ease, box-shadow 150ms ease;
}

.confirm-button:hover {
  border-color: var(--myelin);
  box-shadow: inset 0 0 0 1px var(--myelin);
}

.confirm-button--primary {
  border-color: var(--myelin);
  background: var(--myelin);
  color: var(--slide);
}

.confirm-button--primary:hover {
  border-color: var(--ink);
  box-shadow: inset 0 0 0 1px var(--ink);
}

/* Focus outline comes from the global :focus-visible rule. Do not remove it here. */

:root[data-motion="reduce"] .confirm-button,
:root[data-motion="reduce"] .confirm-button:hover {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .confirm-button {
    transition: none;
  }
}
